// Package schema holds Apple's definitions from the iOS SDK's HealthKit
// headers: type identifiers, enums and metadata keys. healthkit.json is
// generated by ios/scripts/gen_healthkit_schema.py (rerun it after an SDK
// upgrade) and embedded, so the server serves the SDK it was built with.
package schema

import (
	_ "embed"
	"encoding/json"
	"sort"
	"strings"
)

//go:embed healthkit.json
var healthkitJSON []byte

// Type is a type identifier as the SDK declares it. Identifiers are keyed by
// their string value (HKObjectType.identifier); Constant is the Objective-C
// constant's name when it differs from the value.
type Type struct {
	Kind        string `json:"kind"`
	Constant    string `json:"constant,omitempty"`
	Factory     string `json:"factory,omitempty"`
	Available   string `json:"available,omitempty"`
	Deprecated  bool   `json:"deprecated,omitempty"`
	Replacement string `json:"replacement,omitempty"`
	Doc         string `json:"doc,omitempty"`
	// Note is Apple's comment after the declaration, verbatim: a quantity
	// type's canonical unit and aggregation style, a category type's value
	// enum.
	Note string `json:"note,omitempty"`
	// Values names the enum a category type's values (or a characteristic)
	// come from.
	Values string `json:"values,omitempty"`
	// Aggregation is a quantity type's HKQuantityAggregationStyle (case name).
	Aggregation string `json:"aggregation,omitempty"`
}

type Enum struct {
	Name        string `json:"name"`
	SwiftName   string `json:"swiftName,omitempty"`
	Options     bool   `json:"options"`
	Doc         string `json:"doc,omitempty"`
	Available   string `json:"available,omitempty"`
	Deprecated  bool   `json:"deprecated,omitempty"`
	Replacement string `json:"replacement,omitempty"`
	Cases       []Case `json:"cases"`
}

// Case is an enum case. Short is its Swift name (asleepREM), which Rendu
// uses for names on the wire (valueName, workoutActivityTypeName).
type Case struct {
	Name       string `json:"name"`
	Short      string `json:"short"`
	Value      int64  `json:"value"`
	Doc        string `json:"doc,omitempty"`
	Available  string `json:"available,omitempty"`
	Deprecated bool   `json:"deprecated,omitempty"`
}

// MetadataKey is an HKMetadataKey… constant. Key is its string value: what
// an object's metadata uses (HKMetadataKeyFoodType is "HKFoodType").
type MetadataKey struct {
	Key         string `json:"key"`
	Constant    string `json:"constant"`
	Doc         string `json:"doc,omitempty"`
	Available   string `json:"available,omitempty"`
	Deprecated  bool   `json:"deprecated,omitempty"`
	Replacement string `json:"replacement,omitempty"`
	// ValueType is the class the documentation asks for (NSString,
	// NSNumber, NSDate, HKQuantity), and Values the enum of an NSNumber's
	// raw values.
	ValueType string `json:"valueType,omitempty"`
	Values    string `json:"values,omitempty"`
}

type sdk struct {
	SDK struct {
		Version string `json:"version"`
	} `json:"sdk"`
	Types        map[string]Type        `json:"types"`
	Enums        map[string]Enum        `json:"enums"`
	MetadataKeys map[string]MetadataKey `json:"metadataKeys"`

	typeIDs, enumNames, keyNames []string
	// Other names things go by: constants, Swift names.
	typeAlias, enumAlias, keyAlias map[string]string
}

var hk = load(healthkitJSON)

func load(data []byte) *sdk {
	var s sdk
	if err := json.Unmarshal(data, &s); err != nil {
		panic("schema: healthkit.json: " + err.Error())
	}
	s.typeAlias, s.enumAlias, s.keyAlias = map[string]string{}, map[string]string{}, map[string]string{}
	for id, t := range s.Types {
		s.typeIDs = append(s.typeIDs, id)
		if t.Constant != "" {
			s.typeAlias[t.Constant] = id
		}
	}
	for name, e := range s.Enums {
		e.Name = name
		s.Enums[name] = e
		s.enumNames = append(s.enumNames, name)
		if e.SwiftName != "" {
			s.enumAlias[e.SwiftName] = name
		}
	}
	for key, m := range s.MetadataKeys {
		m.Key = key
		s.MetadataKeys[key] = m
		s.keyNames = append(s.keyNames, key)
		s.keyAlias[m.Constant] = key
	}
	for _, names := range [][]string{s.typeIDs, s.enumNames, s.keyNames} {
		sort.Strings(names)
	}
	return &s
}

// Version is the SDK's version, e.g. "27.0".
func Version() string { return hk.SDK.Version }

// TypeIDs lists every type identifier, sorted.
func TypeIDs() []string { return hk.typeIDs }

// LookupType finds a type by its identifier or its constant's name, and
// returns the identifier with it.
func LookupType(name string) (string, Type, bool) {
	if id, ok := hk.typeAlias[name]; ok {
		name = id
	}
	t, ok := hk.Types[name]
	return name, t, ok
}

// SuggestTypes finds the identifiers a mistyped or shortened type name may
// mean: the type it's the short name of ("stepCount", any case), else up
// to five whose identifiers contain it.
func SuggestTypes(name string) []string {
	n := strings.ToLower(strings.TrimSpace(name))
	if n == "" {
		return nil
	}
	var contains []string
	for _, id := range hk.typeIDs {
		l := strings.ToLower(id)
		if l == n || strings.HasSuffix(l, "identifier"+n) || strings.HasSuffix(l, "datatype"+n) {
			return []string{id}
		}
		if strings.Contains(l, n) && len(contains) < 5 {
			contains = append(contains, id)
		}
	}
	return contains
}

// EnumNames lists every enum by its Objective-C name, sorted.
func EnumNames() []string { return hk.enumNames }

// LookupEnum finds an enum by its Objective-C name (HKStateOfMindLabel) or
// its Swift name (HKStateOfMind.Label).
func LookupEnum(name string) (Enum, bool) {
	if objc, ok := hk.enumAlias[name]; ok {
		name = objc
	}
	e, ok := hk.Enums[name]
	return e, ok
}

// MetadataKeys lists every key by its string value, sorted.
func MetadataKeys() []string { return hk.keyNames }

// LookupMetadataKey finds a key by its value (HKFoodType) or its constant's
// name (HKMetadataKeyFoodType).
func LookupMetadataKey(name string) (MetadataKey, bool) {
	if key, ok := hk.keyAlias[name]; ok {
		name = key
	}
	m, ok := hk.MetadataKeys[name]
	return m, ok
}

// Has reports whether value is one of the enum's raw values.
func (e Enum) Has(value int64) bool {
	for _, c := range e.Cases {
		if c.Value == value {
			return true
		}
	}
	return false
}

// Case returns the case named short (its Swift name).
func (e Enum) Case(short string) (Case, bool) {
	for _, c := range e.Cases {
		if c.Short == short {
			return c, true
		}
	}
	return Case{}, false
}
